from src.config_tools import parse_bool

truthy = ['true', ' TRUE ', 'yes', ' YeS ', '1', ' 1 ']
falsy = ['false', ' FALSE ', 'no', ' No ', '0', ' 0 ']
for value in truthy:
    assert parse_bool(value) is True, value
for value in falsy:
    assert parse_bool(value) is False, value
try:
    parse_bool('maybe')
except ValueError:
    pass
else:
    raise AssertionError('unknown text did not raise ValueError')
print('parse_bool focused checks passed')
'@ | python -"

